parameters.functionCode:
// Prepara i dati per Google DLP API
const items = $input.all();
const projectId = $env.GOOGLE_CLOUD_PROJECT_ID;

// Estrai headers e rows dal file Excel
const headers = [];
const rows = [];

if (items.length > 0) {
  const firstItem = items[0].json;

  // Ottieni le colonne
  for (const key in firstItem) {
    headers.push({ name: key });
  }

  // Converti ogni item in una row
  for (const item of items) {
    const row = {
      values: []
    };

    for (const key in item.json) {
      row.values.push({
        stringValue: String(item.json[key] || '')
      });
    }

    rows.push(row);
  }
}

// Costruisci il payload per l'API
const dlpPayload = {
  item: {
    table: {
      headers: headers,
      rows: rows
    }
  },
  deidentifyConfig: {
    recordTransformations: {
      fieldTransformations: [
        {
          fields: headers,
          infoTypeTransformations: {
            transformations: [
              {
                primitiveTransformation: {
                  characterMaskConfig: {
                    maskingCharacter: "*",
                    numberToMask: 0,
                    reverseOrder: false
                  }
                }
              }
            ]
          }
        }
      ]
    }
  },
  inspectConfig: {
    infoTypes: [
      { name: "EMAIL_ADDRESS" },
      { name: "PHONE_NUMBER" },
      { name: "PERSON_NAME" },
      { name: "STREET_ADDRESS" },
      { name: "IP_ADDRESS" },
      { name: "CREDIT_CARD_NUMBER" },
      { name: "DATE_OF_BIRTH" },
      { name: "LOCATION" },
      { name: "URL" }
    ],
    customInfoTypes: [
      {
        infoType: { name: "SOCIAL_MEDIA_USERNAME" },
        regex: { pattern: "@[A-Za-z0-9_]{1,30}" },
        likelihood: "LIKELY"
      },
      {
        infoType: { name: "TWITTER_HANDLE" },
        regex: { pattern: "(?:^|[^@\\w])@([A-Za-z0-9_]{1,15})\\b" },
        likelihood: "LIKELY"
      },
      {
        infoType: { name: "INSTAGRAM_HANDLE" },
        regex: { pattern: "(?:@|(?:instagram\\.com/))([A-Za-z0-9_.]{1,30})" },
        likelihood: "LIKELY"
      }
    ],
    minLikelihood: "POSSIBLE",
    includeQuote: true
  }
};

return [
  {
    json: {
      projectId: projectId,
      payload: dlpPayload,
      originalHeaders: headers,
      userEmail: $node["Webhook - Upload Excel"].json.body.email || 'user@example.com'
    }
  }
];

// Processa la risposta DLP e ricostruisci i dati
const response = $input.first().json;
const originalHeaders = $node["Prepare DLP Request"].json.originalHeaders;

// Estrai la tabella de-identificata
const deidentifiedTable = response.item.table;

// Converti in formato per Excel
const outputData = [];

for (const row of deidentifiedTable.rows) {
  const rowObj = {};

  for (let i = 0; i < originalHeaders.length; i++) {
    const headerName = originalHeaders[i].name;
    const value = row.values[i].stringValue || '';
    rowObj[headerName] = value;
  }

  outputData.push({
    json: rowObj
  });
}

// Aggiungi metadati per l'email
outputData[0].json._metadata = {
  userEmail: $node["Prepare DLP Request"].json.userEmail,
  processedAt: new Date().toISOString(),
  rowsProcessed: outputData.length
};

return outputData;

